const html = $input.first().json.data || '';
const idPattern = /AdDetails\?ad=(\d+)/gi;
const foundIds = [];
let m;
while ((m = idPattern.exec(html)) !== null) {
  if (!foundIds.includes(m[1])) foundIds.push(m[1]);
  if (foundIds.length >= 10) break;
}

if (foundIds.length === 0) {
  return [{
    json: {
      warning: 'НЕ БЕА ПРОНАЈДЕНИ огласи на страница 1. Или страницата не се врати како очекувано, или URL/параметрите се промениле. Провери го суровиот HTML во излезот на "Fetch Search Page 1" нод.'
    }
  }];
}

return foundIds.map(id => ({ json: { adId: id, url: `https://reklama5.mk/AdDetails?ad=${id}` } }));

const html = $json.data || '';
const url = $json.url || '';
const adId = $json.adId || '';

function decodeEntities(str) {
  return str.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();
}
function stripTags(str) {
  return decodeEntities(str.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ')).trim();
}

if (!html) {
  return { json: { adId, url, ERROR: 'Немаше HTML одговор (можеби failed fetch) - провери го Fetch Listing Detail нодот директно за овој ред.' } };
}

const cleanHtml = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ');

let title = '';
const h1Match = cleanHtml.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
if (h1Match) title = stripTags(h1Match[1]);

const priceRegex = /([\d]{1,3}(?:[.,]\d{3})*(?:[.,]\d+)?)\s*(€|МКД|ден\.?)/i;
let priceRaw = '';
let priceCurrency = '';
if (h1Match) {
  const afterH1 = cleanHtml.slice(h1Match.index + h1Match[0].length, h1Match.index + h1Match[0].length + 1500);
  const priceMatch = afterH1.match(priceRegex);
  if (priceMatch) {
    priceRaw = `${priceMatch[1]} ${priceMatch[2]}`.trim();
    priceCurrency = /€/.test(priceMatch[2]) ? '€' : 'МКД';
  }
}
if (!priceRaw) {
  const anyPrice = cleanHtml.match(priceRegex);
  if (anyPrice) {
    priceRaw = `${anyPrice[1]} ${anyPrice[2]}`.trim();
    priceCurrency = /€/.test(anyPrice[2]) ? '€' : 'МКД';
  }
}

// Best-effort breadcrumb: text between 'Недвижности' and the h1 title
let breadcrumb = '';
const nedvIdx = cleanHtml.indexOf('Недвижности');
if (nedvIdx !== -1 && h1Match && h1Match.index > nedvIdx) {
  const chunk = cleanHtml.slice(nedvIdx, h1Match.index);
  breadcrumb = stripTags(chunk).slice(0, 200);
}

const sellerLabelIdx = cleanHtml.indexOf('Се продава од');
let sellerType = 'НЕ Е ПРОНАЈДЕН блокот "Се продава од"';
if (sellerLabelIdx !== -1) {
  const block = cleanHtml.slice(sellerLabelIdx, sellerLabelIdx + 2500);
  sellerType = /<img\b/i.test(block) ? 'Агенција (има слика)' : 'Приватно лице (нема слика)';
}

return {
  json: {
    adId,
    url,
    title,
    priceRaw,
    priceCurrency: priceCurrency || 'НЕ Е ПРЕПОЗНАЕНА',
    isEurAndAbove100k: priceCurrency === '€',
    breadcrumbGuess: breadcrumb,
    sellerTypeDetection: sellerType
  }
};
